import java.util.*;
import java.io.*;

public class Main {
    static int[][] blur(int[][] image) {
        // Write your solution here
        return image;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int r = (int) in.nval;
        in.nextToken();
        int c = (int) in.nval;
        int[][] image = new int[r][c];
        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++) {
                in.nextToken();
                image[i][j] = (int) in.nval;
            }
        int[][] res = blur(image);
        StringBuilder sb = new StringBuilder();
        for (int[] row : res) {
            for (int j = 0; j < row.length; j++) sb.append(row[j]).append(j + 1 < row.length ? " " : "\n");
        }
        System.out.print(sb);
    }
}
